pub fn upgrade(&self) -> Option<Rc<'a, T>> {
    if self.strong_count() > 0 {
        // Increment the strong count since we are upgrading to a strong reference
        self.inc_weak();
        Some(Rc {
            inner: self.inner.clone(), // Assuming inner can be cloned
        })
    } else {
        None
    }
}
